<main class="auth-layout"><div class="auth-brand-panel"><a class="brand brand--light" href="<?= url() ?>"><img src="<?= photo(setting('logo')) ?>" width="55" height="55" alt=""><span><strong>SHREE JI</strong><small>GAS INDUSTRIES</small></span></a><div><span class="eyebrow">ACCOUNT RECOVERY</span><h1>A fresh start<br>for your workspace.</h1><p>Verify your 6-digit code and set a new, secure password.</p></div></div><div class="auth-form-panel"><div class="auth-form"><?php if(!$valid): ?><span class="eyebrow">SESSION EXPIRED</span><h2>Invalid or expired code.</h2><div class="admin-alert admin-alert--error" role="alert"><?= e($error ?: 'This password reset link is invalid or has expired. Please request a new code.') ?></div><a class="btn btn-primary" href="<?= url('admin/forgot') ?>">Request a new code <?= icon('arrow-right-line') ?></a><?php elseif(!$verified): ?><span class="eyebrow">STEP 2 OF 3 · CODE VERIFICATION</span><h2>Enter 6-digit OTP.</h2><p>We sent a 6-digit verification code to <strong><?= e($targetEmail ?: 'your email address') ?></strong>. Enter the code below to verify.</p><?php if($error): ?><div class="admin-alert admin-alert--error" role="alert"><?= e($error) ?></div><?php endif ?><form method="post" action="<?= url('admin/reset') ?>?token=<?= e(rawurlencode($token)) ?>"><?= csrfField() ?><input type="hidden" name="token" value="<?= e($token) ?>"><input type="hidden" name="action" value="verify_otp"><label for="resetOtp">6-Digit Verification Code</label><input id="resetOtp" name="otp" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" required autocomplete="one-time-code" placeholder="123456" autofocus style="font-size: 20px; font-weight: 700; letter-spacing: 6px; text-align: center;"><button class="btn btn-primary" type="submit">Verify Code <?= icon('check-double-line') ?></button></form><a class="auth-forgot" href="<?= url('admin/forgot') ?>">Didn’t receive code? Send again</a><?php else: ?><span class="eyebrow">STEP 3 OF 3 · SET PASSWORD</span><h2>Choose a new password.</h2><p>Verification successful! Enter and confirm your new administrator password.</p><?php if($error): ?><div class="admin-alert admin-alert--error" role="alert"><?= e($error) ?></div><?php endif ?><form method="post" action="<?= url('admin/reset') ?>?token=<?= e(rawurlencode($token)) ?>"><?= csrfField() ?><input type="hidden" name="token" value="<?= e($token) ?>"><input type="hidden" name="action" value="set_password"><label for="resetPassword">New Password</label><div class="password-input-wrap"><input id="resetPassword" name="password" type="password" minlength="12" maxlength="72" required autocomplete="new-password" placeholder="At least 12 characters" autofocus><button type="button" class="btn-toggle-pass" data-target="resetPassword" aria-label="Toggle password visibility" title="Show/hide password"><?= icon('eye-line') ?></button></div><small>Use at least 12 characters with a mix of letters, numbers, and symbols.</small><label for="resetConfirm">Confirm New Password</label><div class="password-input-wrap"><input id="resetConfirm" name="confirm_password" type="password" minlength="12" maxlength="72" required autocomplete="new-password" placeholder="Re-enter your new password"><button type="button" class="btn-toggle-pass" data-target="resetConfirm" aria-label="Toggle password visibility" title="Show/hide password"><?= icon('eye-line') ?></button></div><button class="btn btn-primary" type="submit">Update Password &amp; Sign In <?= icon('check-line') ?></button></form><?php endif ?><a class="auth-back" href="<?= url('admin/login') ?>"><?= icon('arrow-left-line') ?> Back to sign in</a></div></div></main>
